**HAL 版本**：
```c
static void DCMIPP_CSI_WritePHYReg(CSI_TypeDef *hcsi, uint32_t reg_msb, uint32_t reg_lsb, uint32_t val)
{
  /* For writing the 4-bit testcode MSBs */
  /* Set testen to high */
  SET_BIT(hcsi->PTCR1, CSI_PTCR1_TWM);         // PTCR1 |= TWM

  /* Set testclk to high */
  SET_BIT(hcsi->PTCR0, CSI_PTCR0_TCKEN);       // PTCR0 |= TCKEN

  /* Place 0x00 in testdin */
  SET_BIT(hcsi->PTCR1, CSI_PTCR1_TWM);         // PTCR1 |= TWM  (no change)

  /* Set testclk to low */
  CLEAR_REG(hcsi->PTCR0);                      // PTCR0 = 0

  /* Set testen to low */
  CLEAR_REG(hcsi->PTCR1);                      // PTCR1 = 0

  /* Place the 8-bit word corresponding to the testcode MSBs in testdin */
  SET_BIT(hcsi->PTCR1, reg_msb & 0xFFU);       // PTCR1 = reg_msb (SET_BIT with a value = OR with value, since PTCR1 was 0, result = reg_msb)

  /* Set testclk to high */
  SET_BIT(hcsi->PTCR0, CSI_PTCR0_TCKEN);       // PTCR0 |= TCKEN

  /* For writing the 8-bit testcode LSBs */
  /* Set testclk to low */
  CLEAR_REG(hcsi->PTCR0);                      // PTCR0 = 0

  /* Set testen to high */
  SET_BIT(hcsi->PTCR1, CSI_PTCR1_TWM);         // PTCR1 |= TWM

  /* Set testclk to high */
  SET_BIT(hcsi->PTCR0, CSI_PTCR0_TCKEN);       // PTCR0 |= TCKEN

  /* Place the 8-bit word test data in testdin */
  SET_BIT(hcsi->PTCR1, CSI_PTCR1_TWM | (reg_lsb & 0xFFU));   // PTCR1 |= TWM | reg_lsb

  /* Set testclk to low */
  CLEAR_REG(hcsi->PTCR0);                      // PTCR0 = 0

  /* Set testen to low */
  CLEAR_REG(hcsi->PTCR1);                      // PTCR1 = 0

  /* For writing the data */
  /* Place the 8-bit word corresponding to the page offset in testdin */
  SET_BIT(hcsi->PTCR1, val & 0xFFU);           // PTCR1 |= val

  /* Set testclk to high */
  SET_BIT(hcsi->PTCR0, CSI_PTCR0_TCKEN);       // PTCR0 |= TCKEN

  /* Finish by setting testclk to low */
  CLEAR_REG(hcsi->PTCR0);                      // PTCR0 = 0
}
```

**NuttX 版本**：
```c
static void dcmipp_csi_write_phyreg(uint32_t reg_msb, uint32_t reg_lsb, uint32_t val)
{
  /* For writing the 4-bit testcode MSBs: set testen + testclk high */
  CSI->PTCR1 |= CSI_PTCR1_TWM;
  CSI->PTCR0 |= CSI_PTCR0_TCKEN;

  /* Set testclk low (falling edge latches testdin) */
  CSI->PTCR0 = 0;

  /* Set testen low */
  CSI->PTCR1 = 0;

  /* Place the testcode MSBs in testdin */
  CSI->PTCR1 = reg_msb & 0xff;

  /* Set testclk high */
  CSI->PTCR0 |= CSI_PTCR0_TCKEN;

  /* For writing the testcode LSBs: testclk low, testen high */
  CSI->PTCR0 = 0;
  CSI->PTCR1 |= CSI_PTCR1_TWM;
  CSI->PTCR0 |= CSI_PTCR0_TCKEN;

  /* Place the testcode LSBs + write strobe in testdin */
  CSI->PTCR1 = CSI_PTCR1_TWM | (reg_lsb & 0xff);

  /* Testclk low latches the register address */
  CSI->PTCR0 = 0;
  CSI->PTCR1 = 0;

  /* Place the data in testdin */
  CSI->PTCR1 = val & 0xff;

  /* Testclk high programs the data */
  CSI->PTCR0 |= CSI_PTCR0_TCKEN;
  CSI->PTCR0 = 0;
}
```

让我逐位对比：

HAL:
1. PTCR1 |= TWM
2. PTCR0 |= TCKEN
3. PTCR1 |= TWM （无变化）
4. PTCR0 = 0 (CLEAR_REG)
5. PTCR1 = 0 (CLEAR_REG)
6. PTCR1 |= (reg_msb & 0xFF)  → 由于 PTCR1=0，所以 PTCR1 = reg_msb & 0xFF
7. PTCR0 |= TCKEN
8. PTCR0 = 0
9. PTCR1 |= TWM
10. PTCR0 |= TCKEN
11. PTCR1 |= (TWM | (reg_lsb & 0xFF))  → 由于 PTCR1 刚被置为 TWM，所以 PTCR1 = TWM | reg_lsb
12. PTCR0 = 0
13. PTCR1 = 0
14. PTCR1 |= (val & 0xFF)  → PTCR1 = val
15. PTCR0 |= TCKEN
16. PTCR0 = 0

NuttX:
1. PTCR1 |= TWM
2. PTCR0 |= TCKEN
3. (无)
4. PTCR0 = 0
5. PTCR1 = 0
6. PTCR1 = reg_msb & 0xFF  （同 HAL 第6步）
7. PTCR0 |= TCKEN
8. PTCR0 = 0
9. PTCR1 |= TWM
10. PTCR0 |= TCKEN
11. PTCR1 = TWM | reg_lsb  （同 HAL 第11步，因为 PTCR1 当前为 TWM，|= TWM|reg_lsb → TWM|reg_lsb）
12. PTCR0 = 0
13. PTCR1 = 0
14. PTCR1 = val & 0xFF
15. PTCR0 |= TCKEN
16. PTCR0 = 0

两者完全一致！NuttX 版本省略了 HAL 的第 3 步（PTCR1 |= TWM，无变化操作），但这是 no-op，不影响结果。

