static uint32_t imx335_phy_read(uint32_t reg_msb, uint32_t reg_lsb)
{
    uint32_t val;
    volatile int i;

    /* Entry: testen(TWM) high, testclk on, one edge */
    CSI->PTCR1 = CSI_PTCR1_TWM;
