    for (i = 0; i < 100; i++) { }

    /* Read data: testen low, one edge, sample TDO */
    CSI->PTCR1 = 0;
    CSI->PTCR0 |= CSI_PTCR0_TCKEN;
    for (i = 0; i < 100; i++) { }
