void *stm32n6_ltdc_swap_fg_buffer(void)
{
  struct stm32n6_ltdc_dev_s *priv = g_ltdc_dev;
  void *safe_buffer;

  if (priv == NULL)
    return NULL;

  /* Swap buffers */
  if (priv->fg_idx == 0)
    {
      priv->fg_idx = 1;
      safe_buffer = priv->fg_buffer2;
    }
  else
    {
      priv->fg_idx = 0;
      safe_buffer = priv->fg_buffer;
    }

  /* Update LTDC Layer1 framebuffer address (shadow) and reload during
   * vertical blanking to avoid tearing. */
  void *display_buf = (priv->fg_idx == 0) ? priv->fg_buffer : priv->fg_buffer2;
  putreg32((uint32_t)(uintptr_t)display_buf, STM32_LTDC_L1CFBAR);
  modifyreg32(STM32_LTDC_SRCR, 0, LTDC_SRCR_VBR);

  return safe_buffer;
}
