**扫描逻辑**(简化单点):
```c
int stm32n6_gt9xxx_scan(int *x, int *y, bool *pressed)
{
  uint8_t buf[4];
  uint8_t status;

  gt9xxx_rd_reg(GT9XXX_GSTID_REG, &status, 1);

  if ((status & 0x0f) > 0 && (status & 0x0f) <= g_gt_tnum)
    {
      /* 清标志 */
      uint8_t z = 0;
      gt9xxx_wr_reg(GT9XXX_GSTID_REG, &z, 1);

      /* 读第一个触摸点 */
      gt9xxx_rd_reg(GT9XXX_TP1_REG, buf, 4);
      /* buf[0]: 高字节X, buf[1]: 低字节X, buf[2]: 高字节Y, buf[3]: 低字节Y */
      *x = ((buf[0] & 0x0f) << 8) | buf[1];
      *y = ((buf[2] & 0x0f) << 8) | buf[3];
      *pressed = true;
      return 1;
    }

  *pressed = false;
  return 0;
}
```

