**轮询线程**:
```c
static void *gt9xxx_input_thread(FAR void *arg)
{
  struct gt9xxx_input_s *priv = arg;
  int x, y;
  bool pressed;
  struct touch_sample_s sample;
  struct timespec now, diff;
  int64_t idle_us;

  while (priv->running)
    {
      if (stm32n6_gt9xxx_scan(&x, &y, &pressed) > 0)
        {
          /* 新触摸帧 */
          priv->last_x = x; priv->last_y = y;
          clock_gettime(CLOCK_MONOTONIC, &priv->last_touch);
          sample.npoints = 1;
          sample.point[0].id = 0;
          sample.point[0].flags = (priv->pressed ? TOUCH_MOVE : TOUCH_DOWN)
                                  | TOUCH_ID_VALID | TOUCH_POS_VALID;
          sample.point[0].x = x;
          sample.point[0].y = y;
          priv->pressed = true;
          touch_event(priv->lower.priv, &sample);
        }
      else
        {
          /* 无新帧:如果按压超过 HOLD_MS 未更新,报 UP */
          clock_gettime(CLOCK_MONOTONIC, &now);
          diff = timespec_sub(now, priv->last_touch);
          idle_us = diff.tv_sec * 1000000 + diff.tv_nsec / 1000;
          if (priv->pressed && idle_us > GT9XXX_HOLD_US)
            {
              sample.npoints = 1;
              sample.point[0].id = 0;
              sample.point[0].flags = TOUCH_UP | TOUCH_ID_VALID | TOUCH_POS_VALID;
              sample.point[0].x = priv->last_x;
              sample.point[0].y = priv->last_y;
              priv->pressed = false;
              touch_event(priv->lower.priv, &sample);
            }
        }

      nxsig_usleep(GT9XXX_POLL_USEC);  /* 10ms */
    }
  return NULL;
}
