**设计定稿**:

新建 `stm32n6_gt9xxx_input.c`(arch 层 lower-half touchscreen 驱动):
- 复用 `stm32n6_gt9xxx_scan()`(已有,导出)
- 轮询线程每 10ms 读一次
- 触摸保持 debounce(60ms 无更新报 UP)
- `touch_register()` 注册 `/dev/input0`,maxpoint=1
- 支持单点触摸(touch point 0)

**触摸保持设计细节**:
- GT9xxx 触摸期间,每帧更新 buffer status + 坐标
- 我们的 scan 每次读 GSTID:有触点 → 返回 1;无触点(0x80 或 0x00)→ 返回 0
- 关键:GT9xxx 静止触摸时可能降低上报率,所以"无新帧"不等于"抬起"
- debounce:60ms 无新帧才报 UP

**关于 clock**:用 `clock_gettime(CLOCK_MONOTONIC)` + `timespec_sub`(NuttX 提供?)。NuttX 有 `clock_systime_timespec` 和 `timespec_sub`(在 time.h)。我用 `timespec_sub`。

实际上 NuttX 提供 `timespec_sub(ts1, ts2, &ts3)` 在 `<time.h>`。或者直接自己算。

**文件内容**:

```c
/****************************************************************************
 * arch/arm/src/stm32n6/stm32n6_gt9xxx_input.c
 *
 * GT9xxx capacitive touchscreen lower-half driver for the NuttX
 * touchscreen upper-half (/dev/input0).
 *
 * Reuses the bit-bang I2C scan from stm32n6_gt9xxx.c and pushes
 * touch events through the standard NuttX touchscreen framework
 * (touch_register / touch_event), so LVGL can read them from
 * /dev/input0.
 *
 ****************************************************************************/

#include <nuttx/config.h>
#include <sys/types.h>
#include <stdbool.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <debug.h>
#include <pthread.h>
#include <time.h>
#include <sched.h>

#include <nuttx/kmalloc.h>
#include <nuttx/signal.h>
#include <nuttx/input/touchscreen.h>

#include "arm_internal.h"
#include "stm32n6_gt9xxx.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define GT9XXX_INPUT_DEVNAME  "/dev/input0"
#define GT9XXX_POLL_USEC      (10 * 1000)   /* 10 ms poll period */
#define GT9XXX_HOLD_MS        60            /* hold pressed this long after the last update */
#define GT9XXX_THREAD_STACK   2048

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct gt9xxx_input_s
{
  struct touch_lowerhalf_s lower;  /* Touchscreen lower half (must be first) */
  pthread_t thread;                /* Polling thread */
  bool running;                    /* True while the polling thread runs */
  bool pressed;                    /* Current touch-down state */
  struct timespec last_update;     /* Time of the last reported touch */
  uint16_t last_x;                 /* Last reported X */
  uint16_t last_y;                 /* Last reported Y */
};

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static void gt9xxx_input_report(FAR struct gt9xxx_input_s *priv,
                                uint8_t flags, int16_t x, int16_t y)
{
  struct touch_sample_s sample;

  memset(&sample, 0, sizeof(sample));
  sample.npoints = 1;
  sample.point[0].id     = 0;
  sample.point[0].flags  = flags | TOUCH_ID_VALID | TOUCH_POS_VALID;
  sample.point[0].x      = x;
  sample.point[0].y      = y;

  touch_event(priv->lower.priv, &sample);
}

static void gt9xxx_input_elapsed_us(FAR const struct timespec *from,
                                    FAR int64_t *us)
{
  struct timespec now;
  struct timespec diff;

  clock_gettime(CLOCK_MONOTONIC, &now);
  timespec_sub(&now, from, &diff);
  *us = (int64_t)diff.tv_sec * 1000000 + diff.tv_nsec / 1000;
}

static FAR void *gt9xxx_input_thread(FAR void *arg)
{
  FAR struct gt9xxx_input_s *priv = (FAR struct gt9xxx_input_s *)arg;
  int x;
  int y;
  bool pressed;
  int64_t idle_us;

  while (priv->running)
    {
      if (stm32n6_gt9xxx_scan(&x, &y, &pressed) > 0)
        {
          /* New touch frame from the GT9xxx */

          priv->last_x = (uint16_t)x;
          priv->last_y = (uint16_t)y;
          clock_gettime(CLOCK_MONOTONIC, &priv->last_update);

          gt9xxx_input_report(priv,
                              priv->pressed ? TOUCH_MOVE : TOUCH_DOWN,
                              x, y);
          priv->pressed = true;
        }
      else if (priv->pressed)
        {
          /* No new frame: the IC may be idle between reports while the
           * finger is held still.  Only report UP after the hold time.
           */

          gt9xxx_input_elapsed_us(&priv->last_update, &idle_us);
          if (idle_us > GT9XXX_HOLD_MS * 1000)
            {
              gt9xxx_input_report(priv, TOUCH_UP,
                                  priv->last_x, priv->last_y);
              priv->pressed = false;
            }
        }

      nxsig_usleep(GT9XXX_POLL_USEC);
    }

  return NULL;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int stm32n6_gt9xxx_input_register(void)
{
  FAR struct gt9xxx_input_s *priv;
  pthread_attr_t attr;
  struct sched_param param;
  int ret;

  priv = (FAR struct gt9xxx_input_s *)
         kmm_zalloc(sizeof(struct gt9xxx_input_s));
  if (priv == NULL)
    {
      return -ENOMEM;
    }

  priv->lower.maxpoint = 1;
  priv->running = true;

  ret = touch_register(&priv->lower, GT9XXX_INPUT_DEVNAME, 1);
  if (ret < 0)
    {
      kmm_free(priv);
      return ret;
    }

  pthread_attr_init(&attr);
  pthread_attr_setstacksize(&attr, GT9XXX_THREAD_STACK);

  ret = pthread_create(&priv->thread, &attr, gt9xxx_input_thread, priv);
  if (ret < 0)
    {
      touch_unregister(&priv->lower, GT9XXX_INPUT_DEVNAME);
      kmm_free(priv);
      return ret;
    }

  return OK;
}
