**putarea**(核心,memcpy 到 fb):
```c
static int stm32n6_lcd_putarea(FAR struct lcd_dev_s *dev,
                               fb_coord_t row_start, fb_coord_t row_end,
                               fb_coord_t col_start, fb_coord_t col_end,
                               FAR const uint8_t *buffer,
                               fb_coord_t stride)
{
  FAR uint16_t *fb = (FAR uint16_t *)g_ltdc_fb;
  fb_coord_t cols = col_end - col_start + 1;
  fb_coord_t rows = row_end - row_start + 1;
  fb_coord_t row;

  for (row = 0; row < rows; row++)
    {
      memcpy(&fb[(row_start + row) * STM32N6_LCD_XRES + col_start],
             buffer + row * (stride > 0 ? stride : cols * 2),
             cols * 2);
    }
  return OK;
}
