/* Cache/MPU diagnostics - one-shot on the first putarea.  Determines why
 * the framebuffer memcpy is so slow (~19ms for 160KB) by measuring the
 * framebuffer read/write speed against a plain static buffer and dumping
 * the MPU/MAIR state that decides the framebuffer's cache attributes.
 */

#define LCD_DIAG_NWORDS  2048   /* 8KB */

static uint32_t g_lcd_diag_scratch[LCD_DIAG_NWORDS] aligned_data(32);

static void stm32n6_lcd_cache_diag(void)
{
  uint32_t sctlr;
  uint32_t mpu_ctrl;
  uint32_t mair0;
  uint32_t mair1;
  uint32_t t0;
  uint32_t c_wfb;
  uint32_t c_rfb;
  uint32_t c_ws;
  uint32_t c_rs;
  uint32_t i;
  FAR uint32_t *fb = (FAR uint32_t *)g_ltdc_fb;
  volatile uint32_t sink = 0;

  sctlr    = getreg32(0xe000ed00);
  mpu_ctrl = getreg32(0xe000ed94);
  mair0    = getreg32(0xe000edc0);
  mair1    = getreg32(0xe000edc4);

  t0 = getreg32(STM32N6_LCD_DWT_CYCCNT);
  for (i = 0; i < LCD_DIAG_NWORDS; i++) fb[i] = 0x12345678u;
  c_wfb = getreg32(STM32N6_LCD_DWT_CYCCNT) - t0;

  t0 = getreg32(STM32N6_LCD_DWT_CYCCNT);
  for (i = 0; i < LCD_DIAG_NWORDS; i++) sink += fb[i];
  c_rfb = getreg32(STM32N6_LCD_DWT_CYCCNT) - t0;

  t0 = getreg32(STM32N6_LCD_DWT_CYCCNT);
  for (i = 0; i < LCD_DIAG_NWORDS; i++) g_lcd_diag_scratch[i] = 0x87654321u;
  c_ws = getreg32(STM32N6_LCD_DWT_CYCCNT) - t0;

  t0 = getreg32(STM32N6_LCD_DWT_CYCCNT);
  for (i = 0; i < LCD_DIAG_NWORDS; i++) sink += g_lcd_diag_scratch[i];
  c_rs = getreg32(STM32N6_LCD_DWT_CYCCNT) - t0;

  syslog(LOG_INFO,
         "LCD cache diag: SCTLR=0x%08lx(C=%lu) MPU_CTRL=0x%08lx "
         "MAIR0=0x%08lx MAIR1=0x%08lx\n",
         (unsigned long)sctlr, (unsigned long)((sctlr >> 2) & 1),
         (unsigned long)mpu_ctrl, (unsigned long)mair0, (unsigned long)mair1);
  syslog(LOG_INFO,
         "LCD cache diag: fbW=%lu fbR=%lu | scratchW=%lu scratchR=%lu cyc "
         "(8KB each)\n",
         (unsigned long)c_wfb, (unsigned long)c_rfb,
         (unsigned long)c_ws, (unsigned long)c_rs);
}
