**read：**
```c
static ssize_t stm32n6_video_read(FAR struct file *filep, FAR char *buffer, size_t buflen)
{
  FAR struct stm32n6_video_dev_s *priv = &g_video_dev;
  ssize_t ret;

  if (buffer == NULL) return -EINVAL;
  if (buflen < STM32N6_VIDEO_FRMSIZE) return -EINVAL;

  if (!priv->streaming)
    {
      /* 自动启动（方便使用） */
      ret = stm32n6_video_start();
      if (ret < 0) return ret;
    }

  /* 等一帧 */
  ret = nxsem_wait(&priv->frame_sem);
  if (ret < 0) return ret;

  priv->frame_ready = false;
  priv->seq++;

  /* 从 fb 拷贝帧给用户 */
  memcpy(buffer, (FAR void *)stm32n6_board_get_framebuffer(), STM32N6_VIDEO_FRMSIZE);

  return STM32N6_VIDEO_FRMSIZE;
}
```

