/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: stm32n6_aton_aie_initialize
 *
 * Description:
 *   Initialize the STM32N6 Neural-ART NPU lower-half driver and register
 *   it with the AI Engine upper half.  Called once during board
 *   initialization.
 *
 *   Steps performed here:
 *     1. Allocate the lower-half private structure.
 *     2. Enable the NPU clock (RCC AHB5ENR.NPUEN).
 *     3. Release the NPU from reset (RCC AHB5RSTR.NPURST).
 *     4. Attach + enable the NPU interrupt lines (NVIC 53..56).
 *     5. Register the device with the AI Engine upper half.
 *
 *   Security note: the NPU CACHEAXI RAM (RISAF8, 0x343C0000) and the NPU
 *   master access (RIMC) must be granted by the FSBL before the NPU can
 *   touch memory.  See the FSBL regression code (stm32n6_fsbl_regress.c,
 *   REGRESS_MASTER_NPU) for the RIF/RISAF grant pattern.
 *
 ****************************************************************************/

int stm32n6_aton_aie_initialize(void)
{
  FAR struct stm32n6_aton_lowerhalf_s *priv;
  uint32_t regval;
  int ret;
  int i;

  /* Allocate the lower-half private structure */

  priv = kmm_zalloc(sizeof(struct stm32n6_aton_lowerhalf_s));
  if (priv == NULL)
    {
      _err("ERROR: Failed to allocate STM32N6 ATON lower-half\n");
      return -ENOMEM;
    }

  priv->lower.ops = &g_stm32n6_aton_aie_ops;
  nxmutex_init(&priv->lock);

  /* Enable the NPU clock (RCC AHB5ENR.NPUEN, write-1 to AHB5ENR). */

  regval  = getreg32(STM32_RCC_AHB5ENR);
  regval |= RCC_AHB5ENR_NPUEN;
  putreg32(regval, STM32_RCC_AHB5ENR);

  /* Release the NPU from reset: assert then de-assert NPURST.
   * (RCC AHB5RSTR.NPURST is bit 31; the reset default is asserted.)
   */

  regval  = getreg32(STM32_RCC_AHB5RSTR);
  regval |= RCC_AHB5RSTR_NPURST;
  putreg32(regval, STM32_RCC_AHB5RSTR);

  regval &= ~RCC_AHB5RSTR_NPURST;
  putreg32(regval, STM32_RCC_AHB5RSTR);

  /* Attach and enable the NPU interrupt lines */

  for (i = 0; i < STM32N6_ATON_NIRQS; i++)
    {
      ret = irq_attach(g_stm32n6_aton_npu_irqs[i],
                       stm32n6_aton_npu_irq, priv);
      if (ret < 0)
        {
          _err("ERROR: Failed to attach NPU IRQ %d: %d\n",
               g_stm32n6_aton_npu_irqs[i], ret);

          /* Detach the lines attached so far and bail out */

          while (i > 0)
            {
              i--;
              up_disable_irq(g_stm32n6_aton_npu_irqs[i]);
              irq_detach(g_stm32n6_aton_npu_irqs[i]);
            }

          nxmutex_destroy(&priv->lock);
          kmm_free(priv);
          return ret;
        }

      up_enable_irq(g_stm32n6_aton_npu_irqs[i]);
    }

  /* Register the driver with the AI Engine upper half */

  ret = aie_register(CONFIG_AIE_STM32N6_DEVPATH, &priv->lower);
  if (ret < 0)
    {
      _err("ERROR: Failed to register STM32N6 ATON AIE driver: %d\n", ret);

      for (i = 0; i < STM32N6_ATON_NIRQS; i++)
        {
          up_disable_irq(g_stm32n6_aton_npu_irqs[i]);
          irq_detach(g_stm32n6_aton_npu_irqs[i]);
        }

      nxmutex_destroy(&priv->lock);
      kmm_free(priv);
      return ret;
    }

  _info("STM32N6 ATON AIE driver registered at %s\n",
        CONFIG_AIE_STM32N6_DEVPATH);
  return OK;
}

