 *
 * Neural-ART NPU AI Engine probe for the STM32N647 ATK-DNN647 board.
 *
 * Usage (NSH):  aie_probe
 *
 *  1. open /dev/aie0
 *  2. AIE_CMD_LOAD  -> open an inference session
 *  3. AIE_CMD_FEED_INPUT / AIE_CMD_GET_OUTPUT with a sample
 *     stm32n6_aton_invoke_params block (ATON runtime not linked yet,
 *     so the lower-half stubs return OK)
 *  4. close
 *
 * This verifies the full AI Engine registration chain:
 * board_bringup -> stm32n6_aton_aie_initialize -> aie_register
 * (/dev/aie0) -> upper-half ioctl dispatch -> lower-half callbacks.
 *
 ****************************************************************************/

#include <nuttx/config.h>

#include <sys/ioctl.h>

#include <fcntl.h>
#include <unistd.h>
#include <stdio.h>
#include <string.h>
#include <errno.h>

#include <nuttx/aie/ai_engine.h>
#include <nuttx/aie/stm32n6_aton_aie.h>

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, FAR char *argv[])
{
  struct stm32n6_aton_invoke_params params;
  FAR const char *devpath = CONFIG_EXAMPLES_AIE_PROBE_DEVPATH;
  uint8_t dummy_input[64];
  uint8_t dummy_output[64];
  int fd;
  int ret;

  /* 1. Open the AI Engine device */

  fd = open(devpath, O_RDONLY);
  if (fd < 0)
    {
      fprintf(stderr, "aie_probe: open %s failed: %d\n", devpath, errno);
      return 1;
    }

  printf("aie_probe: opened %s\n", devpath);

  /* 2. Open an inference session (AIE_CMD_LOAD) */

  ret = ioctl(fd, AIE_CMD_LOAD, 0);
  if (ret < 0)
    {
      fprintf(stderr, "aie_probe: AIE_CMD_LOAD failed: %d\n", errno);
      close(fd);
      return 1;
    }

  printf("aie_probe: AIE_CMD_LOAD OK\n");

  /* 3. Exercise feed-input / get-output with a sample parameter block.
   *    The ATON runtime is not linked yet, so the lower-half callbacks
   *    are stubs that return OK.  This still verifies that the ioctl
   *    dispatch reaches the lower-half ops.
   */

  memset(&params, 0, sizeof(params));
  params.model       = NULL;
  params.input       = dummy_input;
  params.output      = dummy_output;
  params.input_size  = sizeof(dummy_input);
  params.output_size = sizeof(dummy_output);

  ret = ioctl(fd, AIE_CMD_FEED_INPUT, (unsigned long)&params);
  if (ret < 0)
    {
      fprintf(stderr, "aie_probe: AIE_CMD_FEED_INPUT failed: %d\n", errno);
      close(fd);
      return 1;
    }

  printf("aie_probe: AIE_CMD_FEED_INPUT OK\n");

  ret = ioctl(fd, AIE_CMD_GET_OUTPUT, (unsigned long)&params);
  if (ret < 0)
    {
      fprintf(stderr, "aie_probe: AIE_CMD_GET_OUTPUT failed: %d\n", errno);
      close(fd);
      return 1;
    }

  printf("aie_probe: AIE_CMD_GET_OUTPUT OK\n");

  /* 4. Close (deinit session) */

  close(fd);
  printf("aie_probe: all AI Engine ops passed\n");
  return 0;
}

