/****************************************************************************
 * apps/examples/cam_save/cam_save_main.c
 *
 * SPDX-License-Identifier: Apache-2.0
 *
 * Licensed to the Apache Software Foundation (ASF) under one or more
 * contributor license agreements.  See the NOTICE file distributed with
 * this work for additional information regarding copyright ownership.
 * The ASF licenses this file to you under the Apache License, Version
 * 2.0 (the "License"); you may not use this file except in compliance
 * with the License.  You may obtain a copy of the License at
 *
 *   http://www.apache.org/licenses/LICENSE-2.0
 *
 * Unless required by applicable law or agreed to in writing, software
 * distributed under the License is distributed on an "AS IS" BASIS,
 * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or
 * implied.  See the License for the specific language governing
 * permissions and limitations under the License.
 *
 * Camera frame capture to TF card (dataset collection).
 *
 * Usage (NSH):  cam_save [nsamples] [label]
 *   nsamples : number of frames to capture (default 20)
 *   label    : class name used in the file name (default "sample")
 *
 * Flow:
 *  1. open /dev/video0, VIDIOC_S_FMT 800x480 RGB565, STREAMON
 *  2. for each sample: read(fd, NULL, 0) frame-sync, then downscale the
 *     LTDC framebuffer (via /dev/fb0) to 96x96 grayscale
 *  3. write a small BMP file to /mnt/sdcard/ (FATFS, mounted by the board)
 *
 * The output files are named {label}_{seq:03d}.bmp, e.g. sample_001.bmp.
 * The card is removed afterwards and read on the host PC for training.
 *
 ****************************************************************************/

#include <nuttx/config.h>

#include <sys/videoio.h>
#include <sys/ioctl.h>
#include <sys/mount.h>

#include <fcntl.h>
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

#include <nuttx/video/fb.h>

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#ifndef CONFIG_EXAMPLES_CAM_SAVE_MOUNTPOINT
#  define CONFIG_EXAMPLES_CAM_SAVE_MOUNTPOINT "/mnt/sdcard"
#endif

#define WIDTH             96
#define HEIGHT            96
#define FRAME_W           800
#define FRAME_H           480

/* BMP header 14 + DIB 40 + data */

#define BMP_HEADER_SIZE   54

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: save_bmp_grayscale
 *
 * Description:
 *   Write a 96x96 8-bit grayscale image as an uncompressed BMP (24bpp
 *   row-padded) so the host PC can load it with OpenCV/Pillow directly.
 *
 ****************************************************************************/

static int save_bmp_grayscale(FAR const char *path,
                              FAR const uint8_t *gray)
{
  FAR uint8_t header[BMP_HEADER_SIZE];
  FAR uint8_t row[WIDTH * 3];
  FILE *fp;
  int x;
  int y;

  fp = fopen(path, "wb");
  if (fp == NULL)
    {
      fprintf(stderr, "cam_save: fopen %s failed: %d\n", path, errno);
      return -1;
    }

  /* BITMAPFILEHEADER (14 bytes) */

  memset(header, 0, sizeof(header));
  header[0] = 'B';
  header[1] = 'M';
  header[2] = (WIDTH * HEIGHT * 3 + BMP_HEADER_SIZE) & 0xff;
  header[3] = ((WIDTH * HEIGHT * 3 + BMP_HEADER_SIZE) >> 8) & 0xff;
  header[4] = 0;
  header[5] = 0;
  header[6] = 0;
  header[7] = 0;
  header[10] = BMP_HEADER_SIZE;           /* data offset */

  /* BITMAPINFOHEADER (40 bytes) */

  header[14] = 40;                        /* header size */
  header[18] = WIDTH & 0xff;              /* width */
  header[19] = (WIDTH >> 8) & 0xff;
  header[22] = HEIGHT & 0xff;             /* height */
  header[23] = (HEIGHT >> 8) & 0xff;
  header[26] = 1;                         /* planes */
  header[28] = 24;                        /* bit count */
  header[34] = (WIDTH * HEIGHT * 3) & 0xff;  /* image size */
  header[35] = ((WIDTH * HEIGHT * 3) >> 8) & 0xff;
  header[36] = ((WIDTH * HEIGHT * 3) >> 16) & 0xff;

  fwrite(header, 1, BMP_HEADER_SIZE, fp);

  /* Pixel rows, bottom-up, each row padded to 4 bytes (96*3 = 288
   * is already 4-aligned so no padding needed).
   */

  for (y = HEIGHT - 1; y >= 0; y--)
    {
      for (x = 0; x < WIDTH; x++)
        {
          uint8_t g = gray[y * WIDTH + x];

          row[x * 3 + 0] = g;
          row[x * 3 + 1] = g;
          row[x * 3 + 2] = g;
        }

      fwrite(row, 1, WIDTH * 3, fp);
    }

  fclose(fp);
  return 0;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, FAR char *argv[])
{
  struct v4l2_format fmt;
  struct fb_planeinfo_s pinfo;
  enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  FAR const char *label = "sample";
  FAR uint16_t *fb = NULL;
  FAR uint8_t *gray;
  char path[128];
  int nsamples = 20;
  int fd;
  int fbfd;
  int i;

  if (argc > 1)
    {
      nsamples = atoi(argv[1]);
    }

  if (argc > 2)
    {
      label = argv[2];
    }

  gray = malloc(WIDTH * HEIGHT);
  if (gray == NULL)
    {
      fprintf(stderr, "cam_save: malloc failed\n");
      return 1;
    }

  /* 1. Open video device and configure format */

  fd = open("/dev/video0", O_RDONLY);
  if (fd < 0)
    {
      fprintf(stderr, "cam_save: open /dev/video0 failed: %d\n", errno);
      free(gray);
      return 1;
    }

  memset(&fmt, 0, sizeof(fmt));
  fmt.fmt.pix.width       = FRAME_W;
  fmt.fmt.pix.height      = FRAME_H;
  fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_RGB565;
  if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0)
    {
      fprintf(stderr, "cam_save: VIDIOC_S_FMT failed: %d\n", errno);
      close(fd);
      free(gray);
      return 1;
    }

  if (ioctl(fd, VIDIOC_STREAMON, &type) < 0)
    {
      fprintf(stderr, "cam_save: VIDIOC_STREAMON failed: %d\n", errno);
      close(fd);
      free(gray);
      return 1;
    }

  /* 2. Open the framebuffer for direct pixel access */

  fbfd = open("/dev/fb0", O_RDONLY);
  if (fbfd < 0)
    {
      fprintf(stderr, "cam_save: open /dev/fb0 failed: %d\n", errno);
      ioctl(fd, VIDIOC_STREAMOFF, &type);
      close(fd);
      free(gray);
      return 1;
    }

  if (ioctl(fbfd, FBIOGET_PLANEINFO, &pinfo) < 0)
    {
      fprintf(stderr, "cam_save: FBIOGET_PLANEINFO failed: %d\n", errno);
      close(fbfd);
      ioctl(fd, VIDIOC_STREAMOFF, &type);
      close(fd);
      free(gray);
      return 1;
    }

  fb = (FAR uint16_t *)(uintptr_t)pinfo.fbmem;
  printf("cam_save: capturing %d frames as '%s' to %s\n",
         nsamples, label, CONFIG_EXAMPLES_CAM_SAVE_MOUNTPOINT);

  /* 3. Capture loop: frame-sync then downscale + save */

  for (i = 0; i < nsamples; i++)
    {
      int x;
      int y;

      /* Frame-sync: read(fd, NULL, 0) waits for the next completed frame
       * (DCMIPP writes it into the LTDC framebuffer).
       */

      if (read(fd, NULL, 0) < 0)
        {
          fprintf(stderr, "cam_save: frame-sync failed: %d\n", errno);
          break;
        }

      /* Downscale 800x480 RGB565 -> 96x96 grayscale (nearest) */

      for (y = 0; y < HEIGHT; y++)
        {
          for (x = 0; x < WIDTH; x++)
            {
              /* Map to source pixel (scale rounding) */

              int sx = (x * FRAME_W) / WIDTH;
              int sy = (y * FRAME_H) / HEIGHT;
              uint16_t px = fb[sy * (pinfo.stride / 2) + sx];
              uint8_t r = (px >> 11) & 0x1f;
              uint8_t g = (px >> 5) & 0x3f;
              uint8_t b = px & 0x1f;

              /* RGB565 -> luminance */

              gray[y * WIDTH + x] =
                (uint8_t)((r * 77 + g * 150 + b * 29) >> 8);
            }
        }

      snprintf(path, sizeof(path),
               "%s/%s_%03d.bmp",
               CONFIG_EXAMPLES_CAM_SAVE_MOUNTPOINT, label, i + 1);

      if (save_bmp_grayscale(path, gray) < 0)
        {
          break;
        }

      printf("cam_save: saved %s\n", path);
    }

  /* 4. Cleanup */

  ioctl(fd, VIDIOC_STREAMOFF, &type);
  close(fbfd);
  close(fd);
  free(gray);
  printf("cam_save: done (%d/%d)\n", i, nsamples);
  return 0;
}

