  {
    putreg32(STM32_RCC_AHB5ENSR, RCC_AHB5ENR_SDMMC1EN);
    putreg32(STM32_RCC_AHB5LPENSR, RCC_AHB5ENR_SDMMC1EN);
    putreg32(STM32_RCC_AHB5RSTCR, RCC_AHB5RSTR_SDMMC1RST);
