/* RISUP (RISC slave attributes): SDMMC1 must be SECURE+PRIVILEGED,
 * exactly like stm32n6_ltdc.c / stm32n6_dcmipp.c do for LTDC1/DCMIPP
 * (both verified on real HW).  IMPORTANT ORDER: this must come BEFORE
 * the AHB5ENSR write below, because the RCC clock-enable bits are
 * security-gated by the RIFSC SEC/PRIV signals -- until the RISC
 * attribute matches the access, the write has no effect and the SDMMC
 * kernel clock path (RIMU) stays isolated -> the command state machine
 * never completes (CPSMACT stuck at 0x2000, STA stays 0).  The
 * bare-metal 38_SD_Card SystemIsolation_Config() sets the same via
 * HAL_RIF_RISC_SetSlaveSecureAttributes(RIF_RISC_PERIPH_INDEX_SDMMC1,
 * SEC|PRIV): RIF_RISC_PERIPH_INDEX_SDMMC1 = RIF_PERIPH_REG1 | SEC21 ->
 * RISC_SECCFGRx[1] bit21 (RIFSC+0x14) and RISC_PRIVCFGRx[1] bit21
 * (RIFSC+0x34).
 */

putreg32(RCC_AHB3ENR_RIFSCEN, STM32_RCC_AHB3ENSR);  /* RIFSC clock on */
modifyreg32(STM32_RIFSC_BASE + 0x14, 0, (1u << 21));  /* SEC21  */
modifyreg32(STM32_RIFSC_BASE + 0x34, 0, (1u << 21));  /* PRIV21 */

/* Enable the SDMMC peripheral clock BEFORE touching any SDMMC register
 * -- without the clock the register reads return 0 and the cmd/data
 * status loops would hang the boot.  Per RM0486 the AHB5ENR bits are
 * security-protected by RIFSC SEC/PRIV signals and ST's LL helper
 * (LL_AHB5_GRP1_EnableClock) enables them via the write-1-to-set alias
 * AHB5ENSR (@0xA60) -- same pattern as stm32n6_gpio.c using AHB4ENSR.
 * Also enable the same bits in AHB5LPENSR (sleep mode) and release the
 * peripheral from reset via AHB5RSTCR (default is released, but this is
 * the RM-recommended clear-alias path).
 */

if (bus_num == 1)
  {
    putreg32(STM32_RCC_AHB5ENSR, RCC_AHB5ENR_SDMMC1EN);
    putreg32(STM32_RCC_AHB5LPENSR, RCC_AHB5ENR_SDMMC1EN);
    putreg32(STM32_RCC_AHB5RSTCR, RCC_AHB5RSTR_SDMMC1RST);
  }
else if (bus_num == 2)
  {
    putreg32(STM32_RCC_AHB5ENSR, RCC_AHB5ENR_SDMMC2EN);
    putreg32(STM32_RCC_AHB5LPENSR, RCC_AHB5ENR_SDMMC2EN);
    putreg32(STM32_RCC_AHB5RSTCR, RCC_AHB5RSTR_SDMMC2RST);
