static int sdmmc_wait_status(struct stm32n6_sdmmc_priv_s *priv,
                              uint32_t mask)
{
  uint32_t timeout = 5000000;
  uint32_t samples = 0;

  while (timeout-- > 0)
    {
      uint32_t status = sdmmc_getreg(priv, SDMMC_STA_OFFSET);
      if (status & SDMMC_STA_CTIMEOUT)
        {
          sdmmc_putreg(priv, SDMMC_ICR_OFFSET,
                       SDMMC_STA_CTIMEOUT);
          return -ETIMEDOUT;
        }

      if (status & mask)
        {
          sdmmc_putreg(priv, SDMMC_ICR_OFFSET, mask);
          return 0;
        }

      /* Periodic STA sampling: tells us whether the command state
       * machine is frozen (always 0x2000 = CPSMACT) or actually
       * moving but too slowly / with unexpected flags. */

      if (samples < 6 && (timeout % 500000) == 0)
        {
          syslog(LOG_INFO,
                 "sdmmc: wait[%lu] mask=0x%08lx STA=0x%08lx\n",
                 (unsigned long)samples, (unsigned long)mask,
                 (unsigned long)status);
          samples++;
        }
    }

  syslog(LOG_ERR, "sdmmc: wait_status timeout (mask=0x%08lx, STA=0x%08lx)\n",
         (unsigned long)mask,
         (unsigned long)sdmmc_getreg(priv, SDMMC_STA_OFFSET));

  return -ETIMEDOUT;
}

